const paths={spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',arrow:'M5 12h14m-6-6 6 6-6 6',up:'M12 19V5m-6 6 6-6 6 6',out:'M7 17 17 7M7 7h10v10',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',map:'M5 6h4v4H5zm10 8h4v4h-4zM9 8h8v6M7 10v6h8',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8z',down:'m6 9 6 6 6-6',chat:'M4 4h16v12H9l-5 5z',folder:'M3 6h7l2 2h9v12H3z',plus:'M12 5v14M5 12h14',search:'M15 15l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',sliders:'M6 3v6m0 4v8M3 9h6M18 3v11m0 4v3m-3-7h6',people:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-3a6 6 0 0 1 12 0v3M16 4a4 4 0 0 1 0 8m1 3a5 5 0 0 1 5 5',link:'m9 15 6-6m-5-3 2-2a5 5 0 0 1 7 7l-2 2M7 11l-2 2a5 5 0 0 0 7 7l2-2',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',undo:'M9 5 3 11l6 6M3 11h11a6 6 0 0 1 6 6',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6zm5 3h4'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const orb='<span class="norma-orb" aria-hidden="true"><i></i></span>';
const av=a=>`<span class="avatar" style="--person:${a.color}">${a.agent[0]}</span>`;
const status=a=>`<span class="status ${a.status}" title="${t(a.status)}" aria-label="${t(a.status)}"><i></i>${t(a.status)}</span>`;
const button=(action,label,i,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${i?icon(i):''}${label}</button>`;
function scopeControls(){return `<div class="scope-controls"><label>${icon('grid')}<select id="scope-space" aria-label="${t('workspace')}"><option value="all">${t('allSpaces')}</option>${spaces.map(s=>`<option value="${s.id}" ${S().space===s.id?'selected':''}>${spaceName(s.id)}</option>`).join('')}</select></label><span>/</span><label><select id="scope-project" aria-label="${t('project')}"><option value="all">${t('allProjects')}</option>${Object.entries(projects).filter(([id])=>S().space==='all'||spaces.find(s=>s.id===S().space).projects.includes(id)).map(([id,p])=>`<option value="${id}" ${S().project===id?'selected':''}>${p.name}</option>`).join('')}</select></label></div>`;}
function frame(n,body){document.body.dataset.view=n;document.documentElement.lang=lang==='zh'?'zh-CN':'en';return `<div class="prototype-frame" data-variant-root="${n}"><header class="app-header"><div class="wordmark">${orb}<b>Norma</b><span>${tr('Agent 指挥中心','Agent command center')}</span></div>${scopeControls()}<div class="app-tools">${button('compare',t('compare'),'grid','tool-button')}${button('language',lang==='zh'?'EN':'中',null,'tool-button')}</div></header><div class="variant-meta"><div><span class="concept-number">0${n}</span><h1>${l(variantInfo[n-1].name)}</h1><span class="concept-axis">${l(variantInfo[n-1].axis)}</span></div><div>${button('canvas',t('canvas'),'out','button subtle')}${button('choose',preference===n?t('chosen'):t('choose'),preference===n?'check':'plus','button choose',`aria-pressed="${preference===n}"`)}</div></div>${body}<footer class="prototype-footer"><span>${t('local')}</span><div>${button('reset',t('reset'),'undo','text-button')}${button('video','', $('#wallpaper').paused?'play':'pause','tool-button',`title="${t('video')}" aria-label="${t('video')}" aria-pressed="${!$('#wallpaper').paused}"`)}<span>${tr('按 1–5 比较形态','Press 1–5 to compare')}</span></div></footer></div>`;}
function avatarStack(list){return `<span class="avatar-stack">${list.slice(0,5).map(av).join('')}${list.length>5?`<span class="avatar">+${list.length-5}</span>`:''}</span>`;}
function progress(a){return `<div class="progress-track"><span style="width:${a.progress/a.total*100}%"></span></div><span class="progress-copy">${a.progress}/${a.total} ${t('steps')}</span>`;}
function check(a){return `<label class="check-target" title="${t('select')} ${a.agent}"><input type="checkbox" data-select="${a.id}" aria-label="${t('select')} ${a.agent} · ${spaceName(a.space)}" ${S().selection.has(a.id)?'checked':''}><span></span></label>`;}
function agentCard(a,compact=false){return `<article class="agent-tile ${S().selection.has(a.id)?'selected':''} ${compact?'compact':''}"><div class="tile-top">${av(a)}<div><strong>${a.agent}</strong><small>${a.engine}</small></div>${status(a)}${check(a)}</div><button class="tile-title" data-chat="${a.id}">${esc(l(a.title))}</button><p>${esc(l(a.summary))}</p><div class="tile-progress">${progress(a)}</div><footer><span>${spaceName(a.space)}</span><button class="text-button" data-chat="${a.id}">${t('chat')}${icon('arrow')}</button></footer></article>`;}
function directiveBox(id='global-input'){const targets=selectedAgents();return `<form class="directive-box" data-command-form><div class="directive-label">${orb}<strong>${tr('给方向，让 Norma 协调执行','Set direction. Let Norma coordinate.')}</strong><span>${targets.length?`${targets.length} ${tr('位已选','selected')}`:tr('先选择 Agent，或在下一步指定目标','Select agents now or choose recipients next')}</span></div><div class="directive-input"><textarea data-testid="${id}" data-global-input rows="1" placeholder="${tr('例如：先收敛桌面验收，官网等结果再更新…','For example: finish desktop review before updating the website…')}">${esc(S().draft)}</textarea><button type="submit" class="button primary" data-testid="prepare-command">${t('preview')}${icon('arrow')}</button></div><div class="directive-targets">${targets.length?targets.map(a=>`<button type="button" class="target-chip" data-toggle-target="${a.id}">${av(a)}${a.agent}${icon('close')}</button>`).join(''):`<span>${tr('每个接收者都会有独立指令与回执','Each recipient gets an independent command and receipt')}</span>`}</div></form>`;}
function rosterRow(a,extra=''){return `<div class="roster-row">${av(a)}<button data-chat="${a.id}"><strong>${a.agent}</strong><small>${esc(l(a.title))}</small></button>${extra||status(a)}</div>`;}
function dialogClose(){return `<button class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button>`;}
function modalHead(title,id,sub=''){return `<header class="modal-header"><div><h2 id="${id}">${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${dialogClose()}</header>`;}
